using System;
using UnityEngine;

public class SpikeSpider : Enemy
{
	public class SpiderIdleRoamState : IdleRoamState
	{
		public new SpikeSpider parent;

		public SpiderIdleRoamState(string name, FSM fsm, SpikeSpider ent)
			: base(name, fsm, ent)
		{
			parent = ent;
			multiAnimIdle = true;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.ToggleMoveSpeedUp(status: false);
		}
	}

	public class SpiderHurtState : EnemyHurtState
	{
		public new SpikeSpider parent;

		public SpiderHurtState(string name, FSM fsm, SpikeSpider ent)
			: base(name, fsm, ent)
		{
			parent = ent;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.ToggleMoveSpeedUp(status: true);
		}
	}

	public class SpiderDazedState(string name, FSM fsm, SpikeSpider ent) : State<SpikeSpider>(name, fsm, ent)
	{
		private float dazedDuration = 1f;

		private int dazedStopwatchID;

		public override void OnEnter()
		{
			dazedStopwatchID = ChaosStopwatch.Begin(dazedDuration);
			parent.anim.Play("IdleDown");
			parent.movement.EndMovement();
		}

		public override void Update()
		{
			if (ChaosStopwatch.Check(dazedStopwatchID))
			{
				fsm.ChangeState((!parent.alerted) ? fsm.defaultStateName : "Chase");
			}
		}
	}

	private NumVarStatMod alertedSpeedUpMod;

	private string speedUpString = "alertedSpeedUpMod";

	private float speedUpValue = 1.5f;

	public override void Awake()
	{
		base.Awake();
		alertedSpeedUpMod = new NumVarStatMod(speedUpString, movement.moveSpeedStat.CurrentValue * speedUpValue, 10, VarStatModType.OverrideWithMods);
	}

	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new RoamState("Roam", fsm, this));
		attackSkillID = "NeutralSpiderSpikes";
		fsm.AddState(new AttackState("Attack", fsm, this));
		fsm.AddState(new ChaseState("Chase", fsm, this));
		fsm.AddState(new EnemyDeadState("Dead", fsm, this));
		fsm.AddState(new EnemyFallState("Fall", fsm, this));
		fsm.AddState(new EnemyFrozenState("Frozen", fsm, this));
		fsm.AddState(new SpiderIdleRoamState("Idle", fsm, this));
		fsm.AddState(new SpiderHurtState("Hurt", fsm, this));
		fsm.AddState(new SpiderDazedState("Dazed", fsm, this));
		fsm.AddState(new LungeState("Lunge", fsm, this, 0, 1, 0f, 3f, 0f)
		{
			attackSkillID = "NeutralSpiderSpikeLunge",
			castingAnimName = "IdleDown",
			attackAnimName = "IdleDown",
			appendFacingDirectionToAtkAnim = false,
			dashSpeed = 20f,
			dashDuration = 0.2f
		});
		fsm.ChangeState(fsm.defaultStateName);
	}

	public override void InitAudio()
	{
		hurtAudioIDs = new string[1] { "SpiderHurt" };
		minPitch = 0.9f;
		maxPitch = 1.1f;
	}

	public override void Start()
	{
		base.Start();
		Attack attack = base.attack;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnCollision));
		base.attack.SetAttackInfo(skillCategory, attackSkillID);
	}

	private void OnCollision(Collider2D col)
	{
		fsm.QueueChangeState("Dazed");
	}

	private void ToggleMoveSpeedUp(bool status)
	{
		if (status)
		{
			movement.moveSpeedStat.AddMod(alertedSpeedUpMod);
		}
		else
		{
			movement.moveSpeedStat.RemoveMod(alertedSpeedUpMod);
		}
	}
}
