		public BaseSpreadShotState(string newName, FSM newFSM, Enemy newEnt, int newReq = 0, int newPriority = 0, float newMin = 0f, float newMax = 0f, float newCD = 0f, bool newAuto = false)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			projectilePrefab = EnemyFireball.Prefab;
			spawnRange = 1.5f;
			projectileCount = 1;
			waveCount = 1;
			waveTime = 0.2f;
		}

		public virtual bool TargetFound()
		{
			if (parent.UpdateTargetInfo(-1f, reqLOS: true) == null)
			{
				ExitTransition();
				return false;
			}
			parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
			parent.anim.Play(castingAnimName);
			targetVector = UpdateTargetVector();
			return true;
		}

		public override void OnEnter()
		{
			if (TargetFound())
			{
				base.OnEnter();
				parent.movement.EndMovement();
				parent.anim.Play(castingAnimName, -1, 0f);
				if (castTime < 0f)
				{
					castTime = StdWindupTime;
				}
				if (holdTime < 0f)
				{
					holdTime = StdWindupTime * 0.5f;
				}
				waveCountdown = waveCount - 1;
				attackInitalized = false;
			}
		}

		public virtual void InitalizeAttack()
		{
			projectileList.Clear();
			projectilesCreated = false;
			projectilesFired = false;
			castStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, castTime / (float)projectileCount, projectileCount);
			positionCount = totalPositionCount - (int)((float)projectileCount * 0.5f);
		}

		public override void ExecuteSkill()
		{
			if (!attackInitalized)
			{
				if (trackTarget && !TargetFound())
				{
					base.ExecuteSkill();
					return;
				}
				attackInitalized = true;
				InitalizeAttack();
			}
			if (!projectilesCreated)
			{
				parent.anim.Play(castingAnimName, -1, 0f);
				if (CreateAllProjectiles())
				{
					projectilesCreated = true;
					holdStopwatchID = ChaosStopwatch.Begin(holdTime);
				}
				return;
			}
			if (!projectilesFired)
			{
				if (!ChaosStopwatch.Check(holdStopwatchID))
				{
					OnProjectileHold();
					return;
				}
				projectilesFired = true;
				FireAllProjectiles();
				if (!loopingCastingAnim)
				{
					parent.anim.Play(castingAnimName, -1, 1f);
				}
				waveStopwatchID = ChaosStopwatch.Begin(waveTime);
			}
			if (waveCountdown > 0)
			{
				if (ChaosStopwatch.Check(waveStopwatchID))
				{
					waveCountdown--;
					attackInitalized = false;
				}
			}
			else
			{
				base.ExecuteSkill();
			}
		}

		public override void ExitTransition()
		{
			if (fsm.HasState("Reposition"))
			{
				fsm.ChangeState("Reposition");
			}
			else
			{
				base.ExitTransition();
			}
		}

