			perpendVec = Globals.GetPerpendicular(calcVector.normalized, strafeRight);
			calcPosition = givenTargetLoc + perpendVec * calcVector.magnitude;
			calcVector = (calcPosition - currentPosition).normalized;
			calcPosition = currentPosition + calcVector * dashRange;
			if (Globals.CheckLine(currentPosition, calcPosition, ChaosCollisions.layerAllWallAndObst))
			{
				return calcVector;
			}
			strafeRight = !strafeRight;
			calcPosition = givenTargetLoc - perpendVec * calcVector.magnitude;
			calcVector = (calcPosition - currentPosition).normalized;
			calcPosition = currentPosition + calcVector * dashRange;
			if (Globals.CheckLine(currentPosition, calcPosition, ChaosCollisions.layerAllWallAndObst))
			{
				return calcVector;
			}
		}
		useStrafe = false;
		calcVector = (currentPosition - givenTargetLoc).normalized;
		if (Globals.CheckCircle(currentPosition + calcVector * 3f, 0.25f, ChaosCollisions.layerAllWallAndObst))
