using System;
using UnityEngine;
public class SuperCoffin : MiniBoss
{
	public class SuperCoffinAttackState : SkillState
	{
		private float delayTime = 0.25f;
		private int delayStopwatchID;
		private bool atkCompleted;
		private float throwTime;
		public new SuperCoffin parent;
		public SuperCoffinAttackState(string newName, FSM newFSM, SuperCoffin newEnt)
			: base(newName, newFSM, newEnt, 0, 0, 0f, 50f, 0f, newAuto: false)
		{
			parent = newEnt;
			usePowerUpEffect = false;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.anim.Play("ThrowRight", -1, 0f);
			windupTime = StdWindupTime;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			exitTime = StdExitTime * 1.5f;
			throwTime = Mathf.Lerp(0.5f, 0.4f, currentDiffValue);
			atkCompleted = false;
		}
		public override void WindupUpdate()
		{
			base.WindupUpdate();
			parent.anim.Play("ThrowRight", -1, 0f);
		}
		public override void ExecuteSkill()
		{
			if (!atkCompleted)
			{
				atkCompleted = true;
				delayStopwatchID = ChaosStopwatch.Begin(delayTime);
				if (parent.UpdateTargetInfo() != null)
				{
					parent.CreateCoffinBlock(parent.transform.position, parent.closestTargetInfo.position, initThrow: true, throwTime);
					parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
				}
				parent.anim.Play("ThrowRight", -1, 0.5f);
			}
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				parent.AllowHurtState(status: true);
				base.ExecuteSkill();
			}
		}
		public override void ExitTransition()
		{
			fsm.ChangeState("Ready");
		}
	}
	public class SuperCoffinJumpAttackState : SkillState
	{
		private ThrownItem jumpScript;
		private BoolVarStatMod airborneStatMod;
		private Vector2 jumpPosition;
		private float jumpHeight;
		private float jumpTime;
		private bool jumpStarted;
		private bool jumpCompleted;
		private int landStopwatchID = -1;
		private int blockCount = 6;
		private float blockRange = 3f;
		private int dropStopwatchID;
		private bool dropStarted;
		private bool dropCompleted;
		private int fallStopwatchID;
		private bool fallStarted;
		private bool fallCompleted;
		public new SuperCoffin parent;
		public SuperCoffinJumpAttackState(string newName, FSM newFSM, SuperCoffin newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
		{
			parent = newEnt;
			usePowerUpEffect = false;
			airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 3);
			jumpScript = parent.GetComponent<ThrownItem>();
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.anim.Play("Jump", -1, 0f);
			windupTime = StdWindupTime * 1.25f;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			exitTime = StdExitTime * 1.25f;
			jumpHeight = Mathf.Lerp(4.5f, 3.5f, currentDiffValue);
			jumpTime = Mathf.Lerp(0.35f, 0.25f, currentDiffValue);
			jumpScript.throwHeight = jumpHeight;
			jumpScript.baseFlightTime = jumpTime;
			jumpScript.isFallingThreshold = 1f;
			ThrownItem thrownItem = jumpScript;
			thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
			jumpScript.ForceNewHeights(0f, jumpHeight);
			jumpStarted = false;
			jumpCompleted = false;
			dropStarted = false;
			dropCompleted = false;
			fallStarted = false;
			fallCompleted = false;
		}
		public override void WindupUpdate()
		{
			base.WindupUpdate();
			parent.anim.Play("Jump", -1, 0f);
		}
		public override void ExecuteSkill()
		{
			if (!jumpStarted)
			{
				jumpStarted = true;
				CameraController.ShakeCamera(0.4f);
				parent.anim.Play("Jump", -1, 0.4f);
				parent.spriteRenderer.sortingLayerName = "UI";
				jumpPosition = parent.transform.position;
				if (parent.UpdateTargetInfo() != null)
				{
					targetVector = parent.closestTargetInfo.position - parent.transform.position;
					if (targetVector.sqrMagnitude > 1.5f)
					{
						jumpPosition += targetVector - targetVector.normalized;
					}
				}
				jumpScript.ThrowToTargetVector(jumpPosition);
				float scale = 0.25f;
				parent.ToggleObjects(status: false);
				parent.airborneStat.Modify(airborneStatMod, addMod: true);
			}
			if (jumpScript.isFalling)
			{
				if (!dropCompleted)
				{
					if (!dropStarted)
					{
						dropStarted = true;
						dropStopwatchID = ChaosStopwatch.Begin(jumpTime * 0.25f);
					}
					if (ChaosStopwatch.Check(dropStopwatchID))
					{
						parent.anim.Play("JumpThrow", -1, 0f);
						dropCompleted = true;
						jumpPosition = parent.transform.position;
						parent.currentCB = parent.CreateCoffinBlock(jumpPosition, jumpPosition, initThrow: false, jumpTime * 0.2f, 2);
						parent.currentCB.ForceNewHeights(jumpHeight + 1f, 0.75f);
						parent.currentCB.throwHeight = jumpHeight + 1f;
						parent.currentCB.isFallingThreshold = 0f;
						parent.currentCB.InitThrow();
					}
					return;
				}
				if (!fallCompleted)
				{
					if (!fallStarted)
					{
						fallStarted = true;
						fallStopwatchID = ChaosStopwatch.Begin(jumpTime * 0.125f);
					}
					if (ChaosStopwatch.Check(fallStopwatchID))
					{
						fallCompleted = true;
						jumpScript.throwHeight = jumpHeight;
						jumpScript.baseFlightTime = jumpTime;
						jumpScript.isFallingThreshold = 0.5f;
						jumpScript.ForceNewHeights(jumpHeight);
						jumpScript.ThrowToTargetVector(jumpPosition);
					}
					return;
				}
				if (!jumpCompleted)
				{
					parent.anim.Play("Fall", -1, 0f);
				}
			}
			if (jumpCompleted && ChaosStopwatch.Check(landStopwatchID))
			{
				base.ExecuteSkill();
				parent.AllowHurtState(status: true);
			}
		}
		public override void OnExit()
		{
			if (jumpStarted && !jumpCompleted)
			{
				OnLanding();
			}
			base.OnExit();
			parent.ToggleObjects(status: true);
			parent.airborneStat.Modify(airborneStatMod, addMod: false);
			ThrownItem thrownItem = jumpScript;
			thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
			if (parent.currentCB != null)
			{
				UnityEngine.Object.Destroy(parent.currentCB.gameObject);
			}
		}
		public override void ExitTransition()
		{
			fsm.ChangeState("Ready");
		}
		public void OnLanding()
		{
			if (dropCompleted)
			{
				jumpCompleted = true;
				parent.ToggleObjects(status: true);
				parent.airborneStat.Modify(airborneStatMod, addMod: false);
				landStopwatchID = ChaosStopwatch.Begin(exitTime);
				UnityEngine.Object.Destroy(parent.currentCB.gameObject);
				jumpPosition = parent.transform.position;
				CreateJumpAttack(jumpPosition);
				CreateBlockRing();
				parent.spriteRenderer.sortingLayerName = "Actor";
				PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, jumpPosition);
				float scale = 0.25f;
				Vector2? soundOrigin = jumpPosition;
				CameraController.ShakeCamera(0.5f);
				parent.anim.Play("Land", -1, 0f);
			}
		}
		private void CreateJumpAttack(Vector2 givenPosition)
		{
			EarthExplosion earthExplosion = ChaosInst<EarthExplosion>(EarthExplosion.Prefab, givenPosition);
			earthExplosion.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			earthExplosion.attackBox.collider.enabled = true;
			earthExplosion.warmUpTime = 0f;
			earthExplosion.waveCount = 0;
			earthExplosion.spikeCount = 0;
			earthExplosion.spawnRange = 1.75f;
			earthExplosion.attackRadius = 2f;
			earthExplosion.emitCountOverride = 4;
			earthExplosion.emitRadiusOverride = 1.75f;
			PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, givenPosition);
			Vector2? soundOrigin = givenPosition;
		}
		private void CreateBlockRing()
		{
			Vector2 normalized = UnityEngine.Random.insideUnitCircle.normalized;
			for (int i = 0; i < blockCount; i++)
			{
				targetVector = Globals.GetRotatedCircleVector(blockCount, i, normalized);
				parent.CreateCoffinBlock(jumpPosition + targetVector, jumpPosition + targetVector * blockRange, initThrow: true, 0.5f, 2);
			}
		}
	}
