			parent.currentCB.rotationCount = 4f;
			parent.currentCB.baseFlightTime = givenTime;
			parent.currentCB.ThrowToTargetVector(givenPosition + givenVector * 1.5f);
			parent.currentCB.baseFlightTime = 0.15f;
			parent.currentCB.throwHeight = 2.5f;
			parent.currentCB.rotateSprite = true;
			parent.currentCB.rotationCount = 0.5f;
			parent.currentCB.jumpCountMax = maxBounceCount;
			parent.currentCB.jumpVector = givenVector;
			parent.currentCB.jumpInterval = 0f;
			parent.currentCB.jumpRange = 2.5f;
		}
	}
