			parent.anim.PlayDirectional(castingAnimName + parent.facingDirection);
			windupTime = StdWindupTime * 1.25f;
			ChaosStopwatch.Stop(windupStopwatchID);
			stabStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, stabInterval, stabCount);
			perpendVector = Globals.GetPerpendicular(targetVector);
			stabComplete = false;
			attackCompleted = false;
			initialAttackStarted = false;
			hurtStateAllowed = false;
			parent.movement.MoveToTarget((Vector2)parent.transform.position - targetVector * 0.15f);
			float scale = 0.3f;
		}
		public override void ExecuteSkill()
		{
			if (!stabComplete)
			{
				if (initialAttackStarted && !initialAttackTimer.IsRunning)
				{
					parent.anim.PlayDirectional("Attack" + parent.facingDirection, -1, 1f);
					parent.movement.MoveToTarget((Vector2)parent.transform.position + targetVector * 4f);
				}
				switch (ChaosStopwatch.CheckInterval(stabStopwatchID))
				{
				case StopwatchState.Ready:
					spawnPosition = (Vector2)parent.hurtBoxTransform.position + perpendVector * UnityEngine.Random.Range(0f - spreadValue, spreadValue);
					CreateLanceStab(spawnPosition, targetVector, windupTime);
					if (!initialAttackStarted && !initialAttackTimer.IsRunning)
					{
						initialAttackTimer.SetDelay(windupTime);
						initialAttackTimer.IsRunning = true;
						initialAttackStarted = true;
					}
					break;
				case StopwatchState.Done:
					stabComplete = true;
					attackStopwatchID = ChaosStopwatch.Begin(windupTime + stabInterval);
					break;
				}
			}
			else if (!attackCompleted)
			{
				if (ChaosStopwatch.Check(attackStopwatchID))
				{
					attackCompleted = true;
					parent.attack.SetAttackInfo(parent.skillCategory, parent.attackSkillID);
					parent.anim.PlayDirectional("Attack" + parent.facingDirection, -1, 0.5f);
				}
			}
			else if (!hurtStateAllowed && parent.anim.AnimPlayed(0.6f))
			{
				hurtStateAllowed = true;
				parent.AllowHurtState(status: true);
				base.ExecuteSkill();
			}
		}
		public override void ExitTransition()
		{
			base.ExitTransition();
			parent.AllowHurtState(status: false);
		}
		private void CreateLanceStab(Vector2 givenPosition, Vector2 givenVector, float givenDelay)
