	private bool CalculateDashVector(bool dashingTowards = true, Transform targetTransform = null)
	{
		Vector2 vector = new Vector2(Random.Range(-1f, 1f), Random.Range(-0.75f, 0.75f));
		Transform transform;
		if (targetTransform == null)
		{
			if (closestTargetInfo == null || !(closestTargetInfo.transform != null))
			{
				movement.dashVector = vector;
				return true;
			}
			transform = closestTargetInfo.transform;
		}
		else
		{
			transform = targetTransform;
		}
		if (dashingTowards)
		{
			movement.dashVector = (transform.position - base.transform.position + (Vector3)vector).normalized;
		}
		else
		{
			movement.dashVector = (base.transform.position - transform.position + (Vector3)vector).normalized;
		}
		return Entity.HasLineOfSight(movement.dashVector * 4.8f + (Vector2)base.transform.position, movement.dashVector * 6.3f + (Vector2)base.transform.position, 8f, ChaosCollisions.layerPit);
	}
	private bool DashOverPits()
	{
		if (Physics2D.LinecastNonAlloc(transform.position, transform.position + (Vector3)movement.moveVector.normalized, castResults, ChaosCollisions.layerPit) > 0 && ChaosStopwatch.Check(pitDashStopwatchID))
		{
			pitDashStopwatchID = ChaosStopwatch.Begin(pitDashCooldown);
			movement.dashVector = ((!(movement.moveVector == Vector2.zero)) ? movement.moveVector.normalized : Entity.GetFacingDirectionVector(facingDirection));
			if (Entity.HasLineOfSight(movement.dashVector * 4.8f + (Vector2)transform.position, movement.dashVector * 6.3f + (Vector2)transform.position, 8f, ChaosCollisions.layerPit))
			{
