using UnityEngine;
public class ExplosionShield : MonoBehaviour
{
	private static GameObject prefab;
	private static GameObject shieldPrefab;
	private static ParticleSystemOverride overrideSettings;
	private Rigidbody2D rigidbody2D;
	private SpriteRenderer spriteRenderer;
	[HideInInspector]
	public Attack attack;
	private CircleCollider2D attackCollider;
	private float attackRadius = 2.75f;
	public Transform followTrans;
	private float destroyTime = 1f;
	[HideInInspector]
	public bool exploded;
	private int explodeStopwatchID;
	[HideInInspector]
	public float explodeTime = 1.25f;
	private float currentTimeVal;
	private ChaosQuickStopwatch attackStopwatch;
	private float attackActiveTime = 0.05f;
	private ChaosQuickStopwatch formFXStopwatch;
	private float formFXTime = 0.2f;
	private bool stopFX;
	private bool armed;
	private bool circleCast;
	private Color alphaColor = Color.white;
	private Animator earthShieldAnim;
	private Vector2 currentPosition;
	private RockMedDebrisEmitter explodeEmitter;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/EnemySkills/ExplosionShield.prefab"));
	public static GameObject ShieldPrefab => shieldPrefab ?? (shieldPrefab = ChaosBundle.Get("Assets/Prefabs/Effects/EarthShield.prefab"));
	private static ParticleSystemOverride OverrideSettings
	{
		get
		{
			if (overrideSettings == null)
			{
			}
			return overrideSettings;
		}
	}
	private void Awake()
	{
		rigidbody2D = GetComponent<Rigidbody2D>();
		spriteRenderer = transform.Find("Sprite").GetComponent<SpriteRenderer>();
		attack = transform.Find("Attack").GetComponent<Attack>();
		attackCollider = attack.GetComponent<CircleCollider2D>();
		attackStopwatch = new ChaosQuickStopwatch(attackActiveTime);
		formFXStopwatch = new ChaosQuickStopwatch(formFXTime);
		exploded = false;
		stopFX = false;
	}
	private void Start()
	{
		PlayFormEffect();
		explodeStopwatchID = ChaosStopwatch.Begin(explodeTime);
		earthShieldAnim = Globals.ChaosInst<Animator>(ShieldPrefab, transform.parent, transform.position);
		earthShieldAnim.AdjustAnimSpeed("Fortify", explodeTime * 0.25f);
		earthShieldAnim.Play("Fortify", -1, 0f);
		string audioID = "RockForm";
		Vector2? soundOrigin = transform.position;
	}
	private void Update()
	{
		if (!exploded)
		{
			currentTimeVal = ChaosStopwatch.GetTimePercentage(explodeStopwatchID);
			if (currentTimeVal >= 1f)
			{
				exploded = true;
				Explode();
				attackStopwatch.IsRunning = true;
				return;
			}
			if (!stopFX && !formFXStopwatch.IsRunning)
			{
				stopFX = currentTimeVal > 0.08f;
				formFXStopwatch.IsRunning = true;
				PlayFormEffect();
			}
			if (!circleCast && currentTimeVal >= 0.4f)
			{
				circleCast = true;
				CastCircle(currentTimeVal);
			}
			if (!armed && currentTimeVal >= 0.8f)
			{
				armed = true;
				earthShieldAnim.speed = 1f;
				earthShieldAnim.Play("Armed", -1, 0f);
			}
			alphaColor.a = Mathf.Lerp(0.6f, 1f, currentTimeVal + 0.5f);
			spriteRenderer.color = alphaColor;
		}
		else
		{
			attackCollider.enabled = attackStopwatch.IsRunning;
		}
	}
	private void LateUpdate()
	{
		if (followTrans != null)
		{
			rigidbody2D.MovePosition(followTrans.position);
		}
	}
	private void CastCircle(float explodePercentage)
	{
		string animName = "Draw";
		Vector3 position = transform.position;
		bool disableWithParentVal = false;
		float castTimeVal = explodeTime * (1f - explodePercentage);
		CastingCirclePool.Spawn(animName, position, disableWithParentVal, null, trackParentVal: true, useCastTimeVal: true, castTimeVal, attackRadius, attackRadius, CastingCircle.enemyColor).transform.localEulerAngles = Vector3.zero;
	}
	private void Explode()
	{
		earthShieldAnim.speed = 1f;
		earthShieldAnim.Play("Unfortify", -1, 0f);
		spriteRenderer.enabled = false;
		attackCollider.radius = attackRadius;
		attackCollider.enabled = true;
		currentPosition = transform.position;
		explodeEmitter = PoolManager.GetPoolItem<RockMedDebrisEmitter>();
		explodeEmitter.EmitSingle(6, currentPosition + Vector2.up * 3f, RockMedDebrisEmitter.CircleExplosionOverride);
		explodeEmitter.EmitSingle(10, currentPosition + Vector2.up * 1.5f, RockMedDebrisEmitter.CircleExplosionOverride);
		explodeEmitter.EmitSingle(6, currentPosition, RockMedDebrisEmitter.CircleExplosionOverride);
		explodeEmitter.EmitSingle(3, currentPosition + Vector2.left * 0.25f, RockMedDebrisEmitter.CircleExplosionOverride);
		explodeEmitter.EmitSingle(3, currentPosition + Vector2.right * 0.25f, RockMedDebrisEmitter.CircleExplosionOverride);
		PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, currentPosition);
		string audioID = "GroundSlam";
		Vector2? soundOrigin = currentPosition;
		audioID = "RockExplode";
		soundOrigin = transform.position;
		CameraController.ShakeCamera();
		Object.Destroy(gameObject, destroyTime);
	}
	private void PlayFormEffect()
	{
		ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("RockFormEffect");
		poolItem.Emit(4, spriteRenderer.transform.position, OverrideSettings);
		poolItem.Emit(3, spriteRenderer.transform.position + Vector3.up * 0.15f, OverrideSettings, null, 0.025f);
		poolItem.Emit(3, spriteRenderer.transform.position + Vector3.up * 0.15f, OverrideSettings, null, 0.05f);
	}
}
