	public class EarthKnightExplosionShieldState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true) : SkillState(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
	{
		public float reqHealthPercentage = 0.625f;
		private ExplosionShield currentES;
		public override bool IsReady()
		{
			return base.IsReady() && parent.health.HealthPercentage <= reqHealthPercentage;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.Play("ChargeAlt", -1, 0f);
			SetInvulnerableStatus(status: true);
			windupTime = StdWindupTime * 2f;
			CreateExplosionShield(windupTime);
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		}
		public override void OnExit()
		{
			base.OnExit();
			SetInvulnerableStatus(status: false);
		}
		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			DeactivatePowerUpEffect();
			parent.anim.Play("Charge", -1, 0.5f);
			SetInvulnerableStatus(status: false);
		}
		private void CreateExplosionShield(float givenTime)
		{
			currentES = ChaosInst<ExplosionShield>(ExplosionShield.Prefab);
			currentES.followTrans = parent.transform;
			currentES.attack.SetAttackInfo(parent.skillCategory, skillID);
			currentES.explodeTime = givenTime;
		}
		private void SetInvulnerableStatus(bool status)
		{
			parent.health.invulnerable = status;
			parent.floorCollider.isTrigger = status;
			parent.health.ignoreKnockbackVarStat.Modify(Health.skillIgnoreMod, status);
			parent.health.ignoreGrab = status;
		}
	}
	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		attackSkillID = "EarthKnightAttack";
		fsm.AddState(new IdleState("Idle", fsm, this)
		{
			multiAnimIdle = true
		});
		fsm.AddState(new GoBackState("GoBack", fsm, this));
		fsm.AddState(new ChaseState("Chase", fsm, this));
		fsm.AddState(new SurroundState("Surround", fsm, this));
		fsm.AddState(new AttackState("Attack", fsm, this));
		fsm.AddState(new EnemyHurtState("Hurt", fsm, this));
		fsm.AddState(new EnemyDeadState("Dead", fsm, this));
