		{
			base.WindupUpdate();
			parent.anim.Play("PointUp", -1, 0f);
		}
		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			parent.anim.Play("PointUp", -1, 1f);
			SoundManager.PlayWithDistAndSPR("StandardHeavySwing", parent.transform.position);
			SoundManager.PlayWithDistAndSPR("EarthExplosionShort", parent.transform.position);
			lanceCreationQueued = true;
		}
		public override void Update()
		{
			base.Update();
			if (lanceCreationQueued)
